using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
namespace ServiceGameV2.Editor {public static class ServiceV16NpcReview {
 public static void Run(){var s=ServiceV16Audit.Open();ServiceForestMood.Apply(s,0);var cast=s.GetComponentInChildren<ServiceResidents>();var cam=s.View;cam.transform.SetParent(null);s.Cockpit.SetActive(false);s.Entity.SetActive(false);s.View.GetComponentInChildren<ServiceHands>().gameObject.SetActive(false);cam.nearClipPlane=.035f;cam.cullingMask=-1;s.Flashlight.enabled=true;
  var log=new List<string>();var dir=Path.Combine(ServiceV16Audit.Work,"PreviewV16Residents");Directory.CreateDirectory(dir);var worker=cast.DepotWorker;worker.rotation=Quaternion.identity;var anim=worker.GetComponent<Animation>();
  foreach(float t in new[]{0f,.55f,1.1f,1.65f,2.25f}){anim.clip.SampleAnimation(worker.gameObject,t);var r=worker.GetComponentInChildren<SkinnedMeshRenderer>();var m=new Mesh();r.BakeMesh(m);var points=m.vertices.Select(v=>r.transform.TransformPoint(v)-worker.position).ToArray();log.Add("Nathan "+t+" x="+points.Min(v=>v.x)+".."+points.Max(v=>v.x)+" z="+points.Min(v=>v.z)+".."+points.Max(v=>v.z)+" minY="+points.Min(v=>v.y));cam.transform.position=worker.position+new Vector3(0,1.63f,2.7f);cam.transform.LookAt(worker.position+Vector3.up*1.4f);ServiceV16Audit.Capture(cam,Path.Combine(dir,"nathan-"+t+".png"));UnityEngine.Object.DestroyImmediate(m);}
  var person=cast.Correll;var idle=person.GetComponent<Animation>();idle.clip.SampleAnimation(person,4);cam.transform.position=person.transform.position+person.transform.forward*2.25f+Vector3.up*1.65f;cam.transform.LookAt(person.transform.position+Vector3.up*1.4f);foreach(var r in s.Properties.Single(p=>p.Index==0).DoorPanel.GetComponentsInChildren<Renderer>())r.enabled=false;ServiceV16Audit.Capture(cam,Path.Combine(dir,"correll.png"));File.WriteAllLines(Path.Combine(ServiceV16Audit.Work,"v16-resident-audit.txt"),log);
 }
}}
